[
  ["Ghost of Tsushima", "Samurai Jin Sakai adopts unconventional stealth tactics as the 'Ghost' to liberate Tsushima Island from a brutal Mongol invasion led by Khotun Khan, testing his honor."],
  ["Uncharted 4: A Thief's End", "Retired treasure hunter Nathan Drake is pulled back in by his long-lost brother Sam to find the lost pirate colony of Libertalia and its immense fortune."],
  ["Uncharted: The Lost Legacy", "Chloe Frazer and Nadine Ross team up to find the ancient Tusk of Ganesh in India, racing against a ruthless warlord funding his rebellion with its power."],
  ["The Witcher 3: Wild Hunt", "Monster hunter Geralt of Rivia searches for his adopted daughter Ciri, who possesses rare powers coveted by the spectral Wild Hunt riders threatening the world."],
  ["Marvel's Spider-Man 2", "Peter Parker and Miles Morales face Kraven the Hunter and a corrupting Venom symbiote, forcing them to unite against escalating threats engulfing New York City."],
  ["Marvel's Spider-Man (Remastered)", "Peter Parker balances his personal life while dismantling Wilson Fisk's criminal empire, only for Mister Negative to exploit the resulting power vacuum with a deadly bio-weapon."],
  ["Tomb Raider Trilogy", "Lara Croft evolves from a shipwrecked survivor on Yamatai into a hardened explorer, battling cults and the shadowy Trinity organization across Siberia, Peru, and Mexico."],
  ["The Last of Us Part I", "Smuggler Joel escorts immune teenager Ellie across a fungal-pandemic-ravaged America, hoping she holds the key to a cure, forming an unbreakable bond along the way."],
